  "version": "operator.tool_doc.v1",
  "method": "POST",
  "path": "/revit/mep-route-workflow",
  "risk": "high",
  "group": "MEP",
  "title": "MEP Route Workflow",
  "description": "One-call duct, pipe, or native conduit route workflow that enforces resolve context -> dry-run -> optional apply -> focused post-change highlight/export. Body mirrors create-mep-route, including stable type IDs, explicit worksetName/worksetId, segmentSizes, and optional fail-closed endpoint joining, plus {apply?:boolean,visualVerify?:boolean,visualViewId?,imageSize?,focusPaddingFt?}. Visual verification is ready only when every created element is found, collected, unhidden, and has a view-specific bounding box in the requested view; otherwise it returns CreatedElementsNotVisibleInView with diagnostics.",
  "example": "apply and visually verify a native conduit or duct route",
  "required_fields": [
    "points"
  ],
  "optional_fields": [
    "kind",
    "frameId",
    "viewId",
    "roomNumber",
    "levelName",
    "levelId",
    "worksetName",
    "worksetId",
    "systemType",
    "ductType",
    "ductTypeId",
    "ductShape",
    "pipeType",
    "pipeTypeId",
    "conduitType",
    "conduitTypeId",
    "ductSize",
    "diameter",
    "pipeSize",
    "segmentSizes",
    "sizePolicy",
    "elevationPolicy",
    "routingMode",
    "connectSegments",
    "connectToExisting",
    "requireExistingEndpointConnections",
    "externalConnectionToleranceFt",
    "verify",
    "defaultOffsetFt",
    "ceilingOffsetFt",
    "apply",
    "visualVerify",
    "visualViewId",
    "imageSize",
    "focusPaddingFt"
  ],
  "enums": {
    "kind": [
      "duct",
      "pipe",
      "conduit"
    ],
    "ductShape": [
      "round",
      "rectangular",
      "oval"
    ],
    "sizePolicy": [
      "explicit_required",
      "use_default_with_warning"
    ],
    "elevationPolicy": [
      "explicit_required",
      "resolve_context_default"
    ],
    "routingMode": [
      "orthogonal",
      "polyline"
    ]
  },
  "units": [
    {
      "unit": "feet",
      "fields": [
        "points[*].x",
        "points[*].y",
        "points[*].z",
        "points[*].xyz",
        "defaultOffsetFt",
        "ceilingOffsetFt",
        "focusPaddingFt"
      ]
    },
    {
      "unit": "pixels",
      "fields": [
        "points[*].xPx",
        "points[*].yPx",
        "imageSize"
      ]
    }
  ],
  "common_errors": [],
  "notes": [
    "Execution order is fixed: resolve context, dry-run route, apply route only if dry-run is not blocked, then highlight/export the applied elements for visual review.",
    "When apply=false the workflow returns DryRunReady and no visual capture because dry-run elements are rolled back.",
    "When apply=true and visualVerify=true, successful responses include visualVerification.capture.path plus AI review checklist text.",
    "Only points is universally required. Route type, system, shape, and size fields are conditional on kind and may use either stable type IDs or names."
  ],
